# Daily research run 2026-11-15: Daniel Tufts, brick-maker (1753-1839), and his son Charles Tufts (1781-1876), founder of Tufts College.
_WYIA = '<a href="https://archive.org/details/genealogiesestat02wyma">Internet Archive</a>'
def _WY(p): return f'Thomas Bellows Wyman, <em>The Genealogies and Estates of Charlestown</em>, vol. 2 (Boston, 1879), p. {p}. {_WYIA}'
_SWIA2 = '<a href="https://archive.org/details/oldcharlestownhi1902sawy">Internet Archive</a>'
def _SW2(p): return f'Timothy T. Sawyer, <em>Old Charlestown: Historical, Biographical, Reminiscent</em> (Boston, 1902), p. {p}. {_SWIA2}'
_CT = "charles-tufts-1781"
PROFILES.append(dict(slug=_CT, name="Charles Tufts (1781&ndash;1876)", dates="17 July 1781&ndash;24 December 1876", town="Charlestown and Somerville, Mass.", born="1781", died="1876", era="19th Century",
  line="Son of Daniel Tufts, brick-maker; farmer and brick-maker; donor of Walnut Hill to Tufts College",
  bio=('<p>Charles Tufts was a farmer and brick-maker who owned a large part of the land in Charlestown that became Somerville in 1842. He is remembered for giving Walnut Hill, and a large tract of land around it, to the Universalists for the college that bears his name. He was the third son of ' + PL("daniel-tufts", "Daniel Tufts, the Charlestown brick-maker") + ', and a grandson of ' + PL("nathan-tufts-cordwainer", "Nathan Tufts, cordwainer") + '.</p>'
    + FIG("charles-tufts-c1860.jpg", "hfig-flow")
    + Q("Charles Tufts was a farmer and brick-maker, and a large land-owner in that part of Charlestown set off as Somerville when it was made a separate town. He was a member of the First Universalist Society, and for many years his horse and carriage could be seen every Sunday in one of the sheds which formerly stood in the churchyard of that society, while, with his wife (he had no children), he was occupying his pew in the church.", _SW2(164))
    + Q("Both Mr. Tufts and his wife took great interest in the Universalist denomination, and he is widely known for his gift of Walnut Hill (now College Hill), and a large tract of land about it, to Tufts College. By this act he became the founder of that institution, which was named in his honor.", _SW2(164))
    + '<p>Wyman records him as born July 17, 1781, the son of Daniel Tufts and Abigail Tufts; married Hannah Robinson of Cambridge, daughter of Jacob, who was born April 25, 1795; &ldquo;donor to the Universalists of the elegant site of Tufts college on Walnut-tree hill, and munificent gifts in money&rdquo;; died Sunday, December 24, 1876, with no children (' + _WY(968) + '). Sawyer gives his age at death as ninety-five (p. 164). In 1815 and 1817 he bought land of Timothy Walker on the Cambridge road, next to land of his brother Nathan (Wyman, p. 968).</p>'
    + FIG("tufts-college-1854.jpg", "hfig-flow")
    + '<p>See also <a href="{P}generations/19th-century.html#charles-tufts">Charles Tufts and Walnut Hill</a> on the 19th Century page, and the family&rsquo;s <a href="{P}businesses.html">brickmaking</a>.</p>'),
  service='<p>Born in 1781, he was too young for Revolutionary service. His father ' + PL("daniel-tufts", "Daniel Tufts") + ' appears in the Revolutionary records of Medford; see that page.</p>',
  family=('<p>Father: ' + PL("daniel-tufts", "Daniel Tufts (1753&ndash;1839), brick-maker") + '. Mother: Abigail Tufts (Wyman, p. 968). Brothers: Daniel Tufts Jr. (b. 31 Dec. 1776, tanner, d. 21 Sept. 1868), Gilbert Tufts (b. 27 Apr. 1778, tanner, d. 7 July 1850), and Nathan Tufts &ldquo;2d&rdquo; (b. 10 Mar. 1786, brick-maker and farmer of Somerville, d. 1 Aug. 1872), father of the grain dealer Nathan Tufts of Warren Avenue (Wyman, p. 968; Sawyer, pp. 163&ndash;164). Uncles: ' + PL("amos-tufts-1762", "Deacon Amos Tufts") + ' and ' + PL("nathan-tufts-1764", "Nathan Tufts of Charlestown") + '. No children.</p>'),
  unverified='<strong>Date of marriage</strong> to Hannah Robinson is not given by Wyman. <strong>Date and terms of the Walnut Hill gift</strong> are not cited from a deed here. Note: Pending further work.'))
SP[_CT] = "<ul><li><strong>Hannah (Robinson) Tufts</strong>, of Cambridge, daughter of Jacob Robinson, born April 25, 1795 (Wyman, vol. 2, p. 968). Marriage date not found.</li></ul>"
