for _s, _r in [("daniel-tufts", [(_CT, "son Charles Tufts (1781&ndash;1876), founder of Tufts College")]), ("nathan-tufts-cordwainer", [(_CT, "grandson Charles Tufts (1781&ndash;1876)")]), ("amos-tufts-1762", [(_CT, "nephew Charles Tufts (1781&ndash;1876)")]), ("nathan-tufts-1764", [(_CT, "nephew Charles Tufts (1781&ndash;1876)")])]:
    REL.setdefault(_s, []); REL[_s] = REL[_s] + _r
_EXTRA_1115 = EXTRA
